mapper.sql:
a.deleted = FALSE AND (


            a.project_id IN #{id}

        FALSE

    OR (a.project_id IS NULL AND (
        (a.owner_type = 1 AND a.owner_id = #{filter.userId})

            OR (a.owner_type = 2 AND a.owner_id = #{filter.teamId})
            OR (a.owner_type = 1 AND EXISTS (
                SELECT 1 FROM afv_team_member m WHERE m.team_id = #{filter.teamId}
                AND m.user_id = a.owner_id AND m.status = 1 AND m.deleted = FALSE
            ))

    ))
)
AND a.project_id = #{filter.projectId}
AND a.type = #{filter.type}
AND a.name LIKE #{filter.keyword} ESCAPE '!'

mapper.select:
SELECT id FROM afv_asset WHERE

    project_id = #{projectId}
    project_id IS NULL AND owner_type = #{ownerType} AND owner_id = #{ownerId}

AND type = #{type} AND name = #{name} AND deleted = FALSE ORDER BY id FOR UPDATE
